pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: from address, an adversarial callee will be deployed instead of fuzzing caddress
    // we fuzz the length and values indirectly by passing arrays; Solidity fuzz will generate dynamic arrays
    function testFuzz_property(address from, uint256 len, uint256 seed) public {
        // keep len in a reasonable bound but allow zero too; require in contract forbids zero-length, so ensure >0
        uint256 l = bound(len, 1, 8);

        // build arrays of addresses and values using seed to diversify
        address[] memory tos = new address[](l);
        uint[] memory vals = new uint[](l);
        for (uint i = 0; i < l; i++) {
            // derive pseudo-random addresses/values from seed and index
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i, "addr")))));
            vals[i] = uint256(keccak256(abi.encodePacked(seed, i, "val")));
        }

        // Deploy a benign helper that always accepts the low-level call and returns successfully
        // Its fallback will return true-encoded data for transferFrom selector to mimic success
        CalleeAccepting helper = new CalleeAccepting();

        // Call c.transfer and capture whether it completed (did not revert) and also capture returned bool
        bool ok;
        bool ret;
        try c.transfer(from, address(helper), tos, vals) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // General property: when the call completes (ok==true), the reference implementation always returns true.
        // We assert that; the mutant that changes final `return true;` to `return false;` will cause this assertion to fail for those inputs.
        // Single assertion as required:
        assertTrue(!ok || ret == true);
    }
}

// Minimal helper that accepts the low-level call.
contract CalleeAccepting {
    // Accept any calldata and return a single bool(true) as ABI-encoded data for compatibility
    fallback() external payable returns (bytes memory) {
        // ABI-encode(true)
        bytes memory ret = abi.encode(true);
        assembly {
            return(add(ret, 32), mload(ret))
        }
    }
}

