        // keep len in a reasonable but wide bound and ensure >0 as required by transfer
        uint256 n = bound(len, 1, 8);

        // build arrays of addresses and values; we will route calls through a malicious helper
        address[] memory tos = new address[](n);
        uint[] memory vals = new uint[](n);

        // Deploy a malicious helper that, if invoked with delegatecall, will write to slot 0
        // which we assume corresponds to some public state in C (e.g., a public uint named transfer)
        Malicious m = new Malicious(seed);

        for (uint i = 0; i < n; i++) {
            // all calls target the malicious contract so its code may run
            tos[i] = address(m);
            // populate values with fuzz-derived data
            vals[i] = uint(keccak256(abi.encode(seed, i)));
        }

        // Call transfer on c; reference implementation uses call, so external code cannot modify c's storage.
        // We observe a public getter on c. The property: some public getter (slot 0) remains unchanged (0)
        // for all inputs under the reference; the delegatecall mutant can make it non-zero.
        bool ok;
        try c.transfer(address(0x1234), address(m), tos, vals) {
            ok = true;
