        // Exactly one assertion reading c's public observable state.
        // We assert that the autogenerated getter for a public uint named "transfer" is still zero.
        // This relies on the reference not allowing its storage to be modified by external code.
        // Note: in the reference contract the storage slot remains untouched by calls; the delegatecall mutant
        // can write to that slot, making this assertion fail for some inputs.
        assertTrue(ok && c.transfer() == 0);
    }
